const incoming = $input.first()?.json?.body || $input.first()?.json || {};

// Si no se envían datos vía Webhook, usamos datos de prueba realistas para test manual
const lead = {
  company_name: incoming.company_name || 'Inmobiliaria Delta Horizon',
  website: incoming.website || 'https://deltahorizon-inmuebles.com',
  industry: incoming.industry || 'Bienes Raíces / Real Estate',
  contact_name: incoming.contact_name || 'Rodrigo Valenzuela',
  contact_role: incoming.contact_role || 'Director Comercial & Co-Founder',
  contact_email: incoming.contact_email || 'rodrigo.v@deltahorizon.com',
  company_size: incoming.company_size || '30 empleados',
  current_challenge: incoming.current_challenge || 'Reciben más de 80 leads diarios de Facebook Ads pero tardan 5 horas en contactarlos y los comerciales pierden tiempo con curiosos sin presupuesto.',
  target_service: incoming.target_service || 'Agente SDR IA en Telegram/WhatsApp con calificación BANT en <60s y sincronización directa a CRM.'
};

return [{ json: lead }];

const lead = $input.first().json;

const systemInstruction = `Eres un Estratega Senior de Outbound B2B, Copywriter de Respuesta Directa (seguidor del marco PAS y Alex Hormozi) y Arquitecto de Soluciones de Inteligencia Artificial.

Tu tarea es analizar los datos de la empresa objetivo, detectar sus puntos de dolor operativos y comerciales más críticos, y redactar un Cold Email hiper-personalizado y de altísima conversión para ofrecer una solución de automatización con IA / n8n.

Estructura de salida JSON requerida:
{
  "executive_diagnosis": "Diagnóstico de 2 líneas sobre la fuga de capital o ineficiencia de la empresa",
  "pain_points": [
    "Punto de dolor 1: Tiempo de respuesta lento y pérdida de velocidad de lead",
    "Punto de dolor 2: Costo de oportunidad del equipo de ventas en tareas repetitivas",
    "Punto de dolor 3: Falta de trazabilidad y calificación temprana de prospectos"
  ],
  "ai_solution_pitch": "Propuesta de valor concreta (ej. Agente SDR en Telegram/WhatsApp integrado con n8n y Google Sheets)",
  "linkedin_icebreaker": "Frase corta, directa y sin clichés para iniciar conversación en LinkedIn DM",
  "cold_email": {
    "subject_options": [
      "Opción 1 con curiosidad",
      "Opción 2 con métrica/beneficio",
      "Opción 3 directa"
    ],
    "body_pas": "Cuerpo del email estructurado en Problema -> Agitación -> Solución -> Llamado a la acción de baja fricción (ej. video loom de 3 min o demo interactiva)",
    "cta": "¿Te parecería bien si te comparto un video de 3 minutos mostrando la arquitectura en vivo?"
  },
  "fit_score": 92, // Número del 1 al 100
  "icp_tier": "Tier A (Hot - Alta Probabilidad de Cierre)" // Tier A | Tier B | Tier C
}`;

const prompt = `Analiza la siguiente empresa y prospecto B2B:
- Empresa: ${lead.company_name}
- Sitio Web: ${lead.website}
- Industria: ${lead.industry}
- Contacto: ${lead.contact_name} (${lead.contact_role})
- Tamaño estimado: ${lead.company_size}
- Cuello de botella actual: ${lead.current_challenge}
- Servicio objetivo: ${lead.target_service}`;

return [{
  json: {
    lead_data: lead,
    payload: {
      contents: [
        {
          role: "user",
          parts: [
            {
              text: `${systemInstruction}\n\n--- DATOS DE ENTRADA ---\n${prompt}`
            }
          ]
        }
      ],
      generationConfig: {
        temperature: 0.6,
        topP: 0.9,
        responseMimeType: "application/json"
      }
    }
  }
}];

const item = $input.first().json;
const lead = $('Preparar Prompt Gemini Pro').first().json.lead_data;

let aiResult = {
  executive_diagnosis: 'Diagnóstico en proceso',
  pain_points: [],
  ai_solution_pitch: '',
  linkedin_icebreaker: '',
  cold_email: {
    subject_options: [],
    body_pas: '',
    cta: ''
  },
  fit_score: 80,
  icp_tier: 'Tier B'
};

try {
  const rawText = item.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  const cleaned = rawText.replace(/```json\n?/g, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  aiResult = { ...aiResult, ...parsed };
} catch (e) {
  aiResult.executive_diagnosis = 'Error al parsear JSON de Gemini: ' + e.message;
}

return [{
  json: {
    fecha: new Date().toISOString(),
    empresa: lead.company_name,
    contacto: lead.contact_name,
    cargo: lead.contact_role,
    email: lead.contact_email,
    industria: lead.industry,
    sitio_web: lead.website,
    tamano: lead.company_size,
    desafio_inicial: lead.current_challenge,
    diagnostico_ejecutivo: aiResult.executive_diagnosis,
    puntos_de_dolor: Array.isArray(aiResult.pain_points) ? aiResult.pain_points.join(' | ') : aiResult.pain_points,
    solucion_propuesta: aiResult.ai_solution_pitch,
    linkedin_icebreaker: aiResult.linkedin_icebreaker,
    asunto_email: aiResult.cold_email?.subject_options?.[0] || 'Optimización con IA',
    asuntos_alternativos: aiResult.cold_email?.subject_options?.join(' || ') || '',
    cuerpo_cold_email: aiResult.cold_email?.body_pas || '',
    cta_email: aiResult.cold_email?.cta || '',
    fit_score: aiResult.fit_score,
    icp_tier: aiResult.icp_tier
  }
}];
